<?php $pageTitle='Enkripsi File'; require '_header.php'; require_dongle();
$uid=$_SESSION['user_id'];$msg='';
$dir=__DIR__.'/../storage/files/';if(!is_dir($dir))mkdir($dir,0770,true);
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['file'])){verify_csrf();try{$f=$_FILES['file'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>MAX_UPLOAD_BYTES)throw new Exception('Upload gagal atau ukuran melebihi 10 MB.');$data=file_get_contents($f['tmp_name']);$enc=encrypt_data($data);$name=bin2hex(random_bytes(16)).'.enc';file_put_contents($dir.$name,$enc);$s=db()->prepare('INSERT INTO encrypted_files(user_id,original_name,stored_name) VALUES(?,?,?)');$s->execute([$uid,basename($f['name']),$name]);log_activity('FILE_ENCRYPTED',basename($f['name']));$msg='File berhasil dienkripsi dan disimpan.';}catch(Throwable $e){$msg=$e->getMessage();}}
$s=db()->prepare('SELECT * FROM encrypted_files WHERE user_id=? ORDER BY id DESC');$s->execute([$uid]);$rows=$s->fetchAll();
?><div class="panel"><h2>Enkripsi dokumen</h2><p class="muted">File dienkripsi menggunakan AES-256-GCM. Maksimal 10 MB.</p><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Pilih file</label><input type="file" name="file" required><button class="btn">Enkripsi File</button></form></div><div class="panel"><h2>File tersimpan</h2><?php foreach($rows as $r):?><div class="record"><div><b><?=e($r['original_name'])?></b><small><?=e($r['created_at'])?></small></div><a class="btn secondary" href="../api/download_file.php?id=<?=$r['id']?>">Dekripsi & Unduh</a></div><?php endforeach;?></div><?php require '_footer.php';?>
